from urllib.parse import parse_qs

def validate(query):
    data = parse_qs(query, keep_blank_values=True)
    errors = {}
    name = data.get("name", [""])[0].strip()
    if not name:
        errors["name"] = "required"
    age = data.get("age", [""])[0]
    if age:
        if not age.isdigit() or not 1 <= int(age) <= 120:
            errors["age"] = "invalid"
    return errors

import secrets
import hmac

def new_token():
    return secrets.token_hex(16)

def check_token(expected, submitted):
    return hmac.compare_digest(expected, submitted)

ALLOWED = {"user", "editor"}

def safe_role(value):
    return value if value in ALLOWED else "user"
